# envcfg.py

import os
import tomllib


class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix, env_mapping=os.environ):
    config = defaults.copy()

    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(toml_config)
        except FileNotFoundError:
            pass
        except tomllib.TOMLDecodeError as e:
            raise ConfigError(f'Error decoding TOML file: {e}')

    for key, value in env_mapping.items():
        if key.startswith(env_prefix):
            env_key = key[len(env_prefix):].replace('__', '.').lower()
            config[env_key] = _coerce_value(value, defaults.get(env_key))

    return config

def _coerce_value(value, default):
    if isinstance(default, int):
        return int(value)
    elif isinstance(default, float):
        return float(value)
    elif isinstance(default, bool):
        return value.lower() in ('true', '1', 'yes')
    elif isinstance(default, str):
        return value
    else:
        raise ConfigError(f'Unsupported type for value: {value}')

# test_envcfg.py

import pytest
from envcfg import load_config, ConfigError


def test_defaults():
    defaults = {'key': 'value'}
    config = load_config(defaults)
    assert config == {'key': 'value'}

def test_toml_file():
    toml_content = b'key = "value"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    config = load_config({}, 'config.toml')
    assert config == {'key': 'value'}


def test_env_variable():
    os.environ['APP__KEY'] = 'value'
    config = load_config({}, env_prefix='APP__')
    assert config == {'key': 'value'}

def test_precedence():
    defaults = {'key': 'default'}
    toml_content = b'key = "toml"'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    os.environ['APP__KEY'] = 'env'
    config = load_config(defaults, 'config.toml', env_prefix='APP__')
    assert config == {'key': 'env'}

def test_coercion_int():
    os.environ['APP__KEY'] = '42'
    config = load_config({'key': 0}, env_prefix='APP__')
    assert config == {'key': 42}

def test_coercion_float():
    os.environ['APP__KEY'] = '3.14'
    config = load_config({'key': 0.0}, env_prefix='APP__')
    assert config == {'key': 3.14}

def test_coercion_bool():
    os.environ['APP__KEY'] = 'true'
    config = load_config({'key': False}, env_prefix='APP__')
    assert config == {'key': True}

def test_missing_toml():
    config = load_config({}, 'missing.toml')
    assert config == {}

def test_missing_env():
    with pytest.raises(ConfigError):
        load_config({'key': 'value'}, env_prefix='APP__')

def test_invalid_toml():
    toml_content = b'invalid toml'
    with open('config.toml', 'wb') as f:
        f.write(toml_content)
    with pytest.raises(ConfigError):
        load_config({}, 'config.toml')

